mapper.select:
SELECT
    mgr.id,
    mgr.goods_id,
    mgr.sell_num,
    mgr.create_time,
    mgr.market_id,
    mgr.discount_rate,
    sp.sale_num,
    sp.`name`,
    sp.img,
    sp.state,
    sp.market_price,
    m.market_name
FROM
market_bind mb
LEFT JOIN market m ON mb.market_id = m.id
LEFT JOIN market_goods_relation mgr ON mgr.market_id = m.id
LEFT JOIN spu sp ON mgr.goods_id = sp.id


        and mb.user_id = #{query.userId}


        and mb.bind_type = #{query.bindType.code}


        and mgr.market_id = #{query.marketId}


        and mgr.relation_type = #{query.relationType}


        and mgr.goods_id = #{query.goodsId}

    ${query.buildInSQL('goodsIdList', 'mgr.goods_id')}

        and sp.`name` like CONCAT('%',#{query.goodsName},'%')


        and sp.category_id = #{query.categoryId}


        and sp.`state` = #{query.spuState}


${query.sortSQL}
